Ext.define("ConfigurarTrazas.model.TrazasModel",{extend:"Ext.data.Model",fields:["traza","activado"]});Ext.define("ConfigurarTrazas.store.TrazasStore",{extend:"Ext.data.Store",model:"ConfigurarTrazas.model.TrazasModel",proxy:{type:"ajax",url:"cargar",reader:{type:"json",root:"data"}},autoLoad:true});Ext.define("ConfigurarTrazas.view.gridTrazas",{extend:"Ext.grid.Panel",alias:"widget.gridTrazas",id:"gridTrazas",store:"TrazasStore",initComponent:function(){this.columns=[{header:perfil.etiquetas.labelColumnActivado,dataIndex:"traza",flex:1},{header:perfil.etiquetas.labelColumnTraza,dataIndex:"activado",flex:1}];this.tbar=[{xtype:"button",id:"buttonActivar",text:perfil.etiquetas.labelBtnActivar,iconCls:"icondistra-activar",disabled:true},"->",Ext.create("Ext.button.Button",{id:"btnAyuda",iconCls:"ayuda",text:perfil.etiquetas.labelBtnAyuda})];this.callParent(arguments)}});Ext.define("ConfigurarTrazas.controller.Configurar",{extend:"Ext.app.Controller",views:["gridTrazas"],stores:["TrazasStore"],models:["TrazasModel"],init:function(){this.control({"viewport > panel":{render:this.onPanelRendered},"#buttonActivar":{click:function(c){var b=c.up("grid");var a=b.getSelectionModel().getSelection()[0].data;Ext.Ajax.request({url:"cambiar",params:{traza:a.traza,activado:a.activado,},callback:function(g,e,d){var f=Ext.decode(d.responseText);if(f.cod==1){mostrarMensaje(f.cod,f.mensaje);b.getStore().load();Ext.getCmp("buttonActivar").disable()}}})}},"#gridTrazas":{beforedeselect:function(a,b,c,f){var e=Ext.getCmp("buttonActivar");var d=e.up("grid");if(!d.getSelectionModel().hasSelection()){Ext.getCmp("buttonActivar").disable()}},beforeselect:function(a,b,c,d){Ext.getCmp("buttonActivar").enable()}}})},onPanelRendered:function(){console.log("The panel was rendered")}});Zeolides.App({modulo:"configurar",name:"ConfigurarTrazas",appFolder:"../../configurar",controllers:["Configurar"],launch:function(){Ext.create("Ext.container.Viewport",{layout:"fit",items:[{xtype:"gridTrazas"}]})}});